function getHoje() {
  const hoje = new Date();
  const dia = String(hoje.getDate()).padStart(2, '0');
  const mes = String(hoje.getMonth() + 1).padStart(2, '0');
  const ano = hoje.getFullYear();
  // padrao dd/mm/yyyy
  return `${dia}/${mes}/${ano}`;
}

// Função para comparar datas
function compararComDataAtual(dataInput: string): 'anterior' | 'hoje' | 'posterior' {
  if (!dataInput || dataInput.length < 10) return 'hoje';
  try {
    // aceita dd/mm/aaaa ou dd-mm-aaaa
    const dataFormatada = dataInput.replace(/\//g, '-');
    const [dia, mes, ano] = dataFormatada.split('-').map(Number);
    if (!dia || !mes || !ano) return 'hoje';
    const dataUsuario = new Date(ano, mes - 1, dia);
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);
    dataUsuario.setHours(0, 0, 0, 0);
    if (dataUsuario < hoje) return 'anterior';
    if (dataUsuario > hoje) return 'posterior';
    return 'hoje';
  } catch {
    return 'hoje';
  }
}

async function salvarPresencasNoBanco(presencas: any, fotosUsuarios: any) {
  try {
    const presencaSnap = await getDocs(collection(db, 'presencas'));
    if (!presencaSnap.empty) {
      const presencaDoc = presencaSnap.docs[0];
      await updateDoc(doc(db, 'presencas', presencaDoc.id), {
        presencas,
        fotosUsuarios,
      });
    } else {
      await setDoc(doc(db, 'presencas', 'atual'), { presencas, fotosUsuarios });
    }
  } catch (error) {
    Alert.alert('Erro', 'Não foi possível salvar as presenças.');
  }
}

function formatarDataInput(text: string) {
  let cleaned = text.replace(/\D/g, '');
  let formatted = '';
  if (cleaned.length > 4) {
    formatted = cleaned.replace(/^(\d{2})(\d{2})(\d{0,4}).*/, '$1/$2/$3');
  } else if (cleaned.length > 2) {
    formatted = cleaned.replace(/^(\d{2})(\d{0,2})/, '$1/$2');
  } else {
    formatted = cleaned;
  }
  return formatted;
}

export default function PresencaScreen() {
  const navigation = useNavigation();

  // novo formato: { [nome]: { datas: string[] } }
  const [presencas, setPresencas] = useState<{ [nome: string]: { datas: string[] } }>({});
  const [loading, setLoading] = useState(true);
  const [editando, setEditando] = useState<{ [nome: string]: boolean }>({});
  const [editandoData, setEditandoData] = useState<{ [key: string]: { [idx: number]: string } }>({});
  const [fotosUsuarios, setFotosUsuarios] = useState<{ [nome: string]: string }>(FOTOS_PADRAO);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const hoje = getHoje();
        const presencaSnap = await getDocs(collection(db, 'presencas'));
        let dataBanco: any = {};
        let fotosBanco: any = {};
        if (!presencaSnap.empty) {
          const presencaDoc = presencaSnap.docs[0];
          dataBanco = presencaDoc.data().presencas || {};
          fotosBanco = presencaDoc.data().fotosUsuarios || {};
        }
        const fotosLocalStr = await AsyncStorage.getItem('fotosUsuarios');
        let fotosLocal = {};
        if (fotosLocalStr) {
          try {
            fotosLocal = JSON.parse(fotosLocalStr);
          } catch {}
        }
        const presencasHoje: { [nome: string]: { datas: string[] } } = {};
        NOMES_USUARIOS.forEach(nome => {
          // compatibilidade: data única (campo 'data') ou novo campo 'datas'
          const banco = dataBanco[nome];
          if (banco) {
            if (Array.isArray(banco.datas)) {
              presencasHoje[nome] = { datas: banco.datas.slice(0, 5) };
            } else if (typeof banco.data === 'string') {
              presencasHoje[nome] = { datas: [banco.data] };
            } else {
              presencasHoje[nome] = { datas: [hoje] };
            }
          } else {
            presencasHoje[nome] = { datas: [hoje] };
          }
        });
        setPresencas(presencasHoje);
        setFotosUsuarios({ ...FOTOS_PADRAO, ...fotosBanco, ...fotosLocal });
      } catch (error) {
        Alert.alert('Erro', 'Não foi possível carregar os dados.');
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // Alterna presença para hoje: adiciona/remove a data de hoje do array
  const handleTogglePresenca = (nome: string) => {
    const hoje = getHoje();
    setPresencas(prev => {
      const atuais = prev[nome]?.datas ? [...prev[nome].datas] : [];
      const existe = atuais.includes(hoje);
      let novas = existe ? atuais.filter(d => d !== hoje) : [hoje, ...atuais].slice(0, 5);
      return { ...prev, [nome]: { datas: novas } };
    });
    setEditando(prev => ({ ...prev, [nome]: true }));
  };

  // altera data específica por índice (para permitir multiplas datas)
  const handleChangeData = (nome: string, idx: number, novaData: string) => {
    const dataFormatada = formatarDataInput(novaData);
    setEditandoData(prev => ({ ...prev, [nome]: { ...(prev[nome] || {}), [idx]: dataFormatada } }));
    setEditando(prev => ({ ...prev, [nome]: true }));

    setPresencas(prev => {
      const atuais = prev[nome]?.datas ? [...prev[nome].datas] : [];
      atuais[idx] = dataFormatada;
      return { ...prev, [nome]: { datas: atuais } };
    });
  };

  const addDate = (nome: string) => {
    setPresencas(prev => {
      const atuais = prev[nome]?.datas ? [...prev[nome].datas] : [];
      if (atuais.length >= 5) return prev;
      return { ...prev, [nome]: { datas: [...atuais, getHoje()] } };
    });
    setEditando(prev => ({ ...prev, [nome]: true }));
  };

  const removeDate = (nome: string, idx: number) => {
    setPresencas(prev => {
      const atuais = prev[nome]?.datas ? [...prev[nome].datas] : [];
      atuais.splice(idx, 1);
      return { ...prev, [nome]: { datas: atuais.length ? atuais : [getHoje()] } };
    });
    setEditando(prev => ({ ...prev, [nome]: true }));
  };

  const handleSalvar = async (nome: string) => {
    // garante formato final: datas únicas e até 5
    const atuais = presencas[nome]?.datas ? Array.from(new Set(presencas[nome].datas)) : [getHoje()];
    const finais = atuais.filter(Boolean).slice(0, 5);
    const novo = { ...presencas, [nome]: { datas: finais } };
    setPresencas(novo);

    try {
      await AsyncStorage.setItem('fotosUsuarios', JSON.stringify(fotosUsuarios));
    } catch {}

    await salvarPresencasNoBanco(novo, fotosUsuarios);
    setEditando(prev => ({ ...prev, [nome]: false }));
    setEditandoData(prev => {
      const novoEditandoData = { ...prev };
      delete novoEditandoData[nome];
      return novoEditandoData;
    });
  };

  // MANTÉM a lógica original de salvamento da foto (salva no banco e no local)
  const handlePickImage = async (nome: string) => {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      allowsEditing: true,
      aspect: [1, 1],
      quality: 0.7,
      base64: false,
    });

    if (!result.canceled && result.assets && result.assets.length > 0) {
      const asset = result.assets[0];

      const manipResult = await ImageManipulator.manipulateAsync(
        asset.uri,
        [{ resize: { width: 280, height: 300 } }],
        {
          compress: 0.3,
          format: asset.uri.toLowerCase().endsWith('.png')
            ? ImageManipulator.SaveFormat.PNG
            : ImageManipulator.SaveFormat.JPEG,
          base64: true,
        }
      );

      let ext = asset.uri.split('.').pop()?.toLowerCase();
      if (ext !== 'jpg' && ext !== 'jpeg' && ext !== 'png') ext = 'jpg';

      const base64Image = `data:image/${ext};base64,${manipResult.base64}`;
      setFotosUsuarios(prev => {
        const novoFotos = { ...prev, [nome]: base64Image };
        AsyncStorage.setItem('fotosUsuarios', JSON.stringify(novoFotos));
        // Salva no banco para todos verem
        salvarPresencasNoBanco(presencas, novoFotos);
        return novoFotos;
      });
      setEditando(prev => ({
        ...prev,
        [nome]: true,
      }));
    }
  };

  if (loading) {
    return (
      <LinearGradient
        colors={['#18152a', '#181a3a']}
        style={styles.bg}
      >
        <View style={styles.container}>
          <ActivityIndicator size="large" color="#ff9800" />
        </View>
      </LinearGradient>
    );
  }

  return (
    <LinearGradient
      colors={['#18152a', '#181a3a']}
      style={styles.bg}
    >
      <View style={styles.container}>
        <View style={styles.headerNeumorphic}>
          <View style={styles.headerRow}>
            <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.navigate('Inicio')}>
  <Image
    source={{ uri: 'https://img.icons8.com/?size=100&id=bIwuxbfp2H2N&format=png&color=000000.png' }}
    style={styles.headerIcon}
  />
</TouchableOpacity>
            <Text style={styles.headerTitle}>Lista de Presença</Text>
            <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.goBack()}>
  <Image
    source={{ uri: 'https://img.icons8.com/?size=100&id=CFDbApIER33U&format=png&color=000000.png' }}
    style={styles.headerIcon}
  />
</TouchableOpacity>
          </View>
        </View>
        <FlatList
          data={NOMES_USUARIOS}
          keyExtractor={item => item}
          contentContainerStyle={styles.list}
          renderItem={({ item }) => {
            const datas = presencas[item]?.datas || [getHoje()];
            const hoje = getHoje();
            const presente = datas.includes(hoje);

            return (
              <View style={styles.userCardWrapper}>
                <View style={styles.userCardBorder} />
                <View style={styles.userCardShadow}>
                  <View style={styles.userCardRow}>
                    {/* Avatar maior, centralizado verticalmente */}
                    <View style={styles.avatarColumn}>
                      <TouchableOpacity onPress={() => handlePickImage(item)}>
                        <Image
                          source={{ uri: fotosUsuarios[item] || FOTOS_PADRAO[item] }}
                          style={styles.avatar}
                        />
                      </TouchableOpacity>
                      <TouchableOpacity onPress={() => handlePickImage(item)}>
                        <Text style={styles.editLabel}>Alterar Foto</Text>
                      </TouchableOpacity>
                    </View>
                    {/* Conteúdo ao lado do avatar */}
                    <View style={styles.userCardContent}>
                      <View style={styles.cardTopRow}>
                        <Text style={styles.userName}>{item}</Text>
                        <View style={{ width: 44, height: 44 }} />
                      </View>
                      <View style={styles.cardBottomRow}>
                        <View style={{ flex: 1 }}>
                          {datas.map((d, idx) => (
                            <View key={idx} style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>
                              <TextInput
                                style={[styles.dateInput, { flex: 1 }]}
                                value={editandoData[item]?.[idx] ?? d}
                                onChangeText={nova => handleChangeData(item, idx, nova)}
                                placeholder="dd/mm/aaaa"
                                maxLength={10}
                                keyboardType="default"
                              />
                              <TouchableOpacity onPress={() => removeDate(item, idx)} style={{ marginLeft: 8 }}>
                                <Text style={{ color: '#ff6b6b', fontSize: 20 }}>✖</Text>
                              </TouchableOpacity>
                            </View>
                          ))}
                          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
                            <TouchableOpacity onPress={() => addDate(item)} disabled={(datas || []).length >= 5} style={{ marginRight: 8 }}>
                              <Text style={{ color: (datas || []).length >= 5 ? '#666' : '#4caf50', fontWeight: 'bold' }}>Adicionar data +</Text>
                            </TouchableOpacity>
                          </View>
                        </View>
                        {editando[item] && (
                          <TouchableOpacity
                            style={styles.saveButton}
                            onPress={() => handleSalvar(item)}
                          >
                            <Text style={styles.saveButtonText}>💾Salvar</Text>
                          </TouchableOpacity>
                        )}
                      </View>
                    </View>
                  </View>
                </View>
              </View>
            );
          }}
        />
      </View>
    </LinearGradient>
  );
}

